def mul_order_mod_prime(a, p):
    # multiplicative order of a modulo prime p
    assert p > 2 and all(p % d for d in range(2, int(p**0.5)+1))
    a %= p
    if math.gcd(a, p) != 1:
        return None
    t = 1
    val = a % p
    while val != 1:
        t += 1
        val = (val * a) % p
        if t > p-1:  # safety
            return None
    return t

def lcm(a, b):
    return a // math.gcd(a, b) * b

def count_residues(N, M):
    counts = {}
    for e in range(N):
        r = pow(2, e, M)
        counts[r] = counts.get(r, 0) + 1
    return counts

def binom(n, k):
    if k < 0 or k > n:
        return 0
    # fast multiplicative
    k = min(k, n-k)
    num = 1
    den = 1
    for i in range(1, k+1):
        num *= (n - k + i)
        den *= i
    return num // den

def compute_probability(N, K, M, counts):
    # DP over residue classes, tracking selection size up to K and sum mod M
    # dp[s][r] = number of ways to select s exponents with total residue r
    dp = [[0]*M for _ in range(K+1)]
    dp[0][0] = 1
    for r, c in counts.items():
        # precompute binomial coefficients for selecting j from this residue class
        max_j = min(c, K)
        choose = [binom(c, j) for j in range(max_j+1)]
        newdp = [[0]*M for _ in range(K+1)]
        for s in range(K+1):
            row = dp[s]
            for t in range(M):
                ways = row[t]
                if ways == 0:
