                    ns = s + j
                    if ns > K:
                        break
                    nt = (t + (j * r) % M) % M
                    newdp[ns][nt] += ways * choose[j]
        dp = newdp
    favorable = dp[K][0]
    total = binom(N, K)
    return favorable, total

